    // 1. Validate output pointers
    if ((momentum == NULL) || (momentum_norm == NULL) || 
        (energy_axis == NULL) || (energy == NULL)) {
        return ADCS_E_NULL;
    }

    // 2. Zero out outputs initially
    momentum->x = 0.0;
    momentum->y = 0.0;
    momentum->z = 0.0;
    *momentum_norm = 0.0;
    energy_axis->x = 0.0;
    energy_axis->y = 0.0;
    energy_axis->z = 0.0;
    *energy = 0.0;

    // 3. Check for null wheels pointer
    if (wheels == NULL) {
        return ADCS_E_NULL;
    }

    // 4. Check count range
    if ((count < 1) || (count > 16)) {
        return ADCS_E_RANGE;
    }

    // Local accumulators
    double total_energy = 0.0;
    adcs_vec3_t energy_axis_vec = {0.0, 0.0, 0.0};
    adcs_vec3_t local_momentum = {0.0, 0.0, 0.0};

    // 5. Iterate through wheels to validate and accumulate
    for (size_t i = 0; i < count; ++i) {
        // Check inertia: finite and positive
        if ((!isfinite(wheels[i].inertia_kg_m2)) || (wheels[i].inertia_kg_m2 <= 0.0)) {
            return ADCS_E_RANGE;
        }

        // Check speed: finite
        if (!isfinite(wheels[i].speed_rad_s)) {
            return ADCS_E_RANGE;
        }

        // Check axis: finite and norm > ADCS_EPS_NORM
        if (!adcs_is_finite_vec3(&wheels[i].axis_body)) {
            return ADCS_E_RANGE;
        }

        double axis_norm = adcs_vec3_norm(&wheels[i].axis_body);
        if (axis_norm <= ADCS_EPS_NORM) {
            return ADCS_E_RANGE;
        }

        // Normalize axis manually since we verified validity
        double inv_norm = 1.0 / axis_norm;
        adcs_vec3_t norm_axis;
        norm_axis.x = wheels[i].axis_body.x * inv_norm;
        norm_axis.y = wheels[i].axis_body.y * inv_norm;
        norm_axis.z = wheels[i].axis_body.z * inv_norm;

        // Calculate kinetic energy for this wheel: e_i = 0.5 * inertia * speed^2
        double e_i = 0.5 * wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s * wheels[i].speed_rad_s;

        // Accumulate total energy
        total_energy += e_i;

        // Accumulate energy axis vector: sum(e_i * normalize(axis_i))
        energy_axis_vec.x += e_i * norm_axis.x;
        energy_axis_vec.y += e_i * norm_axis.y;
        energy_axis_vec.z += e_i * norm_axis.z;
    }

    // 6. Compute cluster momentum using linked library function
    // Pre-validation ensures this will succeed
    adcs_wheel_momentum(wheels, count, &local_momentum);

    // 7. Compute momentum norm (Euclidean norm)
    *momentum_norm = adcs_vec3_norm(&local_momentum);

    // 8. Assign final results
    *momentum = local_momentum;
    *energy_axis = energy_axis_vec;
    *energy = total_energy;

    return ADCS_OK;
}

