        e_i = 0.5 * wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s * wheels[i].speed_rad_s;

        // Accumulate total energy locally
        local_energy += e_i;

        // Normalize axis
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &norm_axis) != ADCS_OK) {
            return ADCS_E_RANGE;
