        // Accumulate energy_axis locally: sum(e_i * normalize(axis_i))
        adcs_vec3_t term = adcs_vec3_scale(&norm_axis, e_i);
        local_energy_axis = adcs_vec3_add(&local_energy_axis, &term);
    }

    // 6. Compute cluster momentum
    if (adcs_wheel_momentum(wheels, count, momentum) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    // 7. Assign accumulated values to outputs only after all validations pass
    *energy = local_energy;
    *energy_axis = local_energy_axis;

